    def test_list_returns_all_tasks(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2))
        tasks = list(repo.list())
        assert len(tasks) == 2

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        snapshot = repo.list()
        # Mutating the snapshot doesn't affect the repo
        snapshot.clear()  # type: ignore[union-attr]
        assert len(list(repo.list())) == 1

    def test_update_replaces_task(self, repo):
        task = make_task(id=1, title="Original")
        repo.add(task)
        updated = make_task(id=1, title="Updated")
        repo.update(updated)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises_keyerror(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=99))

    def test_delete_existing_returns_true(self, repo):
